// Get all incoming form data
const input = $input.first();

const json = input.json || {};
const binary = input.binary || {};

// --------------------------------------------------
// 1. Find uploaded resume automatically
// --------------------------------------------------

const binaryKeys = Object.keys(binary);

if (binaryKeys.length === 0) {
  throw new Error(
    'No resume file was received. Please upload your PDF resume and submit the form again.'
  );
}

let sourceKey = binaryKeys[0];
let uploadedFile = binary[sourceKey];

if (!uploadedFile) {
  throw new Error('The uploaded resume binary could not be found.');
}

const fileName = uploadedFile.fileName || 'resume.pdf';
const mimeType = uploadedFile.mimeType || '';

if (
  mimeType &&
  mimeType !== 'application/pdf' &&
  !fileName.toLowerCase().endsWith('.pdf')
) {
  throw new Error(
    'Please upload a PDF resume. Received: ' + mimeType
  );
}

// --------------------------------------------------
// 2. Find Job Description automatically
// --------------------------------------------------

let jobDescription = '';

// First try common field names
const possibleJDFields = [
  'job_description',
  'jobDescription',
  'Job Description',
  'Job_Description',
  'jd',
  'JD',
  'description',
  'text'
];

for (const field of possibleJDFields) {
  if (
    json[field] !== undefined &&
    json[field] !== null &&
    String(json[field]).trim()
  ) {
    jobDescription = String(json[field]).trim();
    break;
  }
}

// --------------------------------------------------
// 3. If not found, inspect all JSON fields
// --------------------------------------------------

if (!jobDescription) {
  for (const [key, value] of Object.entries(json)) {

    if (typeof value !== 'string') {
      continue;
    }

    const valueTrimmed = value.trim();

    if (!valueTrimmed) {
      continue;
    }

    // Ignore obvious form/system fields
    const ignoredFields = [
      'formmode',
      'submittedAt',
      'timestamp',
      'resume',
      'file'
    ];

    if (ignoredFields.includes(key.toLowerCase())) {
      continue;
    }

    // A JD is usually a reasonably long text field.
    // This prevents small metadata fields being selected.
    if (valueTrimmed.length > 100) {
      jobDescription = valueTrimmed;
      break;
    }
  }
}

// --------------------------------------------------
// 4. Still not found -> show available fields
// --------------------------------------------------

if (!jobDescription) {

  const availableFields = Object.keys(json).join(', ');

  throw new Error(
    'Job Description was not detected. ' +
    'Available form fields: [' +
    availableFields +
    ']. ' +
    'Please check the Job Description field name in the Form Trigger.'
  );
}

// --------------------------------------------------
// 5. Return normalized data
// --------------------------------------------------

return [
  {
    json: {
      job_description: jobDescription,
      resume_file_name: fileName,
      original_binary_field: sourceKey
    },
    binary: {
      data: uploadedFile
    }
  }
];

const resumeText = $json.text || '';
const previous = $('Normalize Uploaded Resume').first().json;

if (!resumeText.trim()) {
  throw new Error('The PDF was received, but no readable text could be extracted. Please upload a text-based PDF resume.');
}

if (!previous.job_description || !previous.job_description.trim()) {
  throw new Error('Job Description was not received.');
}

return [
  {
    json: {
      resume_text: resumeText.trim(),
      job_description: previous.job_description.trim(),
      resume_file_name: previous.resume_file_name
    }
  }
];

const response = $json;

let content = response.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('Groq returned an empty response.');
}

content = content.trim();

if (content.startsWith('```')) {
  content = content.replace(/^```json\\s*/i, '').replace(/^```\\s*/i, '').replace(/\\s*```$/i, '').trim();
}

let analysis;

try {
  analysis = JSON.parse(content);
} catch (error) {
  throw new Error('Groq returned invalid JSON. Raw response: ' + content);
}

const original = $('Prepare Resume and JD').first().json;

return [
  {
    json: {
      success: true,
      resume_file_name: original.resume_file_name,
      analysis: analysis
    }
  }
];

const analysis = $json.analysis || {};
const resumeFile = $json.resume_file_name || 'resume.pdf';

function esc(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function arr(value) {
  return Array.isArray(value) ? value : [];
}

function list(value) {
  const items = arr(value);
  if (!items.length) return '<p class="empty">None identified.</p>';
  return '<ul>' + items.map(x => '<li>' + esc(typeof x === 'string' ? x : JSON.stringify(x)) + '</li>').join('') + '</ul>';
}

function score(value) {
  const n = Number(value || 0);
  return Math.max(0, Math.min(100, Math.round(n)));
}

function scoreClass(value) {
  const n = score(value);
  if (n >= 80) return 'good';
  if (n >= 60) return 'medium';
  return 'low';
}

const technicalRows = arr(analysis.technical_skill_analysis).map(x => `
<tr>
<td>${esc(x.skill)}</td>
<td>${esc(x.importance)}</td>
<td class="${x.found_in_resume ? 'yes' : 'no'}">${x.found_in_resume ? 'Yes' : 'No'}</td>
<td>${esc(x.evidence)}</td>
</tr>`).join('');

const changeBlocks = arr(analysis.recommended_changes).map(x => `
<div class="recommendation">
<div class="priority">${esc(x.priority)}</div>
<h4>${esc(x.section)}</h4>
<p>${esc(x.change)}</p>
<p><strong>Why:</strong> ${esc(x.reason)}</p>
</div>`).join('');

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Resume Analysis Report</title>
<style>
*{box-sizing:border-box}
body{margin:0;background:#f4f6f8;font-family:Arial,Helvetica,sans-serif;color:#202124;line-height:1.6}
.container{max-width:1150px;margin:0 auto;padding:30px 20px}
.header{background:#ffffff;border-radius:16px;padding:32px;margin-bottom:20px;box-shadow:0 3px 15px rgba(0,0,0,.08)}
.header h1{margin:0 0 8px;font-size:32px}
.filename{color:#666;margin-bottom:20px}
.verdict{display:inline-block;padding:10px 18px;border-radius:999px;background:#eef3ff;font-weight:bold}
.scores{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px;margin-bottom:20px}
.score-card{background:#fff;border-radius:14px;padding:22px;text-align:center;box-shadow:0 3px 12px rgba(0,0,0,.06)}
.score-card .label{font-size:14px;color:#666;margin-bottom:8px}
.score-card .number{font-size:34px;font-weight:700}
.good{color:#16803c}.medium{color:#a56a00}.low{color:#c62828}
.section{background:#fff;border-radius:14px;padding:28px;margin-bottom:18px;box-shadow:0 3px 12px rgba(0,0,0,.05)}
.section h2{margin-top:0;border-bottom:1px solid #eee;padding-bottom:10px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
@media(max-width:700px){.grid{grid-template-columns:1fr}}
ul{padding-left:22px}.empty{color:#777;font-style:italic}
.tag{display:inline-block;background:#eef2f5;border-radius:20px;padding:6px 11px;margin:4px;font-size:13px}
table{width:100%;border-collapse:collapse;margin-top:15px}th,td{border:1px solid #ddd;padding:11px;text-align:left}th{background:#f3f4f6}.yes{font-weight:bold}.no{font-weight:bold}
.recommendation{border-left:4px solid #555;background:#f8f9fa;padding:15px;margin:12px 0;border-radius:4px}.priority{font-size:12px;font-weight:bold;text-transform:uppercase;margin-bottom:5px}
.summary-box{background:#f7f9fc;padding:20px;border-radius:10px}
.footer{text-align:center;color:#777;font-size:12px;padding:20px}
</style>
</head>
<body>
<div class="container">

<div class="header">
<h1>AI Resume Analysis</h1>
<div class="filename">Resume analyzed: <strong>${esc(resumeFile)}</strong></div>
<div class="verdict">${esc(analysis.recommendation || 'Analysis Complete')}</div>
</div>

<div class="scores">
<div class="score-card"><div class="label">Overall Match</div><div class="number ${scoreClass(analysis.overall_match_score)}">${score(analysis.overall_match_score)}%</div></div>
<div class="score-card"><div class="label">ATS Score</div><div class="number ${scoreClass(analysis.ats_score)}">${score(analysis.ats_score)}%</div></div>
<div class="score-card"><div class="label">Skills Match</div><div class="number ${scoreClass(analysis.skills_match_score)}">${score(analysis.skills_match_score)}%</div></div>
<div class="score-card"><div class="label">Experience Match</div><div class="number ${scoreClass(analysis.experience_match_score)}">${score(analysis.experience_match_score)}%</div></div>
<div class="score-card"><div class="label">Education Match</div><div class="number ${scoreClass(analysis.education_match_score)}">${score(analysis.education_match_score)}%</div></div>
<div class="score-card"><div class="label">Keyword Match</div><div class="number ${scoreClass(analysis.keyword_match_score)}">${score(analysis.keyword_match_score)}%</div></div>
</div>

<div class="section">
<h2>Candidate Summary</h2>
<p>${esc(analysis.candidate_summary)}</p>
</div>

<div class="grid">
<div class="section">
<h2>Matched Skills</h2>
${list(analysis.matched_skills)}
</div>

<div class="section">
<h2>Missing Skills</h2>
${list(analysis.missing_skills)}
</div>
</div>

<div class="section">
<h2>Important JD Keywords</h2>
${list(analysis.important_jd_keywords)}
</div>

<div class="section">
<h2>Keywords Missing From Resume</h2>
${list(analysis.missing_resume_keywords)}
</div>

<div class="grid">
<div class="section">
<h2>Required Skills</h2>
${list(analysis.required_skills)}
</div>

<div class="section">
<h2>Preferred Skills</h2>
${list(analysis.preferred_skills)}
</div>
</div>

<div class="section">
<h2>Technical Skill Analysis</h2>
<table>
<thead><tr><th>Skill</th><th>Importance</th><th>Found</th><th>Resume Evidence</th></tr></thead>
<tbody>${technicalRows}</tbody>
</table>
</div>

<div class="grid">
<div class="section">
<h2>Experience Analysis</h2>
<p><strong>JD Requirement:</strong><br>${esc(analysis.experience_analysis?.required_experience)}</p>
<p><strong>Candidate Experience:</strong><br>${esc(analysis.experience_analysis?.candidate_experience)}</p>
<p>${esc(analysis.experience_analysis?.analysis)}</p>
</div>

<div class="section">
<h2>Education Analysis</h2>
<p><strong>JD Requirement:</strong><br>${esc(analysis.education_analysis?.job_requirement)}</p>
<p><strong>Candidate Education:</strong><br>${esc(analysis.education_analysis?.candidate_education)}</p>
<p>${esc(analysis.education_analysis?.analysis)}</p>
</div>
</div>

<div class="grid">
<div class="section">
<h2>Resume Strengths</h2>
${list(analysis.resume_strengths)}
</div>

<div class="section">
<h2>Resume Weaknesses</h2>
${list(analysis.resume_weaknesses)}
</div>
</div>

<div class="section">
<h2>ATS Issues</h2>
${list(analysis.ats_issues)}
</div>

<div class="section">
<h2>Recommended Changes</h2>
${changeBlocks || '<p class="empty">No changes identified.</p>'}
</div>

<div class="section">
<h2>Recommended Resume Headline</h2>
<div class="summary-box">${esc(analysis.recommended_headline)}</div>
</div>

<div class="section">
<h2>Recommended Professional Summary</h2>
<div class="summary-box">${esc(analysis.recommended_summary)}</div>
</div>

<div class="section">
<h2>Interview Focus Areas</h2>
${list(analysis.interview_focus_areas)}
</div>

<div class="section">
<h2>Final Verdict</h2>
<p>${esc(analysis.final_verdict)}</p>
</div>

<div class="footer">Generated automatically by n8n + Groq AI</div>

</div>
</body>
</html>`;

return [
  {
    json: {
      html_report: html,
      analysis: analysis,
      resume_file_name: resumeFile
    }
  }
];
